INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-42', 'english-a2', 42, 42, 'Accommodation', 'Reservar alojamiento, preguntar por servicios y entender check-in/check-out.', 25, '{"objective":"Reservar alojamiento, preguntar por servicios y entender check-in/check-out.","sections":[{"type":"grammar","title":"Gramática · Accommodation","body":"Reservar alojamiento, preguntar por servicios y entender check-in/check-out.\n\nI''d like to book a room; Is breakfast included?; check in/out.","example":"I''d like to ___ a room.\nbook","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Accommodation","body":"single room = habitación individual; double room = doble; reservation = reserva; available = disponible; key = llave.","example":"Is breakfast ___?\nincluded","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Accommodation","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"Hello, I''d like to book a double room for two nights. Is breakfast included? Yes, and check-in is from 2 pm. Check-out is at 11 am.","transcript":"Hello, I''d like to book a double room for two nights. Is breakfast included? Yes, and check-in is from 2 pm. Check-out is at 11 am.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Accommodation","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"Hello, I''d like to book a double room for two nights. Is breakfast included? Yes, and check-in is from 2 pm. Chec