INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-43', 'english-a2', 43, 43, 'Holiday activities', 'Hablar de actividades de vacaciones, experiencias y planes.', 25, '{"objective":"Hablar de actividades de vacaciones, experiencias y planes.","sections":[{"type":"grammar","title":"Gramática · Holiday activities","body":"Hablar de actividades de vacaciones, experiencias y planes.\n\ngo sightseeing, go swimming, visit museums; use Past Simple for finished holiday events.","example":"Last summer we ___ sightseeing.\nwent","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Holiday activities","body":"sightseeing = turismo; beach = playa; souvenir = recuerdo; hike = ruta a pie; explore = explorar.","example":"We visited two ___.\nmuseums","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Holiday activities","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"Last summer we went sightseeing in Rome, visited two museums and went swimming at the beach. We bought souvenirs for our friends.","transcript":"Last summer we went sightseeing in Rome, visited two museums and went swimming at the beach. We bought souvenirs for our friends.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Holiday activities","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"Last summer we went sightseeing in Rome, visited two museums and went swimming at the beach. We bought souvenirs for our friends.","e