INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-44', 'english-a2', 44, 44, 'Weather and forecasts', 'Describir el tiempo y entender predicciones con it is/was, there is y going to.', 25, '{"objective":"Describir el tiempo y entender predicciones con it is/was, there is y going to.","sections":[{"type":"grammar","title":"Gramática · Weather and forecasts","body":"Describir el tiempo y entender predicciones con it is/was, there is y going to.\n\nIt''s sunny/cloudy/windy; it''s going to rain when there are signs.","example":"It''s ___ today; the wind is strong.\nwindy","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Weather and forecasts","body":"sunny = soleado; cloudy = nublado; windy = ventoso; forecast = previsión; umbrella = paraguas.","example":"Dark clouds mean it may ___.\nrain","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Weather and forecasts","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"The forecast says it will be windy today. There are dark clouds over the hills, so it''s going to rain this afternoon. Take an umbrella.","transcript":"The forecast says it will be windy today. There are dark clouds over the hills, so it''s going to rain this afternoon. Take an umbrella.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Weather and forecasts","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"The forecast says it will be windy today. There are dark clouds over the hills, so it''s going to rain this afternoon. Take an umbrella.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
