INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-50', 'english-a2', 50, 50, 'Module 5 review', 'Integrar vocabulario práctico para viajes, alojamiento, vacaciones, tiempo, compras, salud y relaciones.', 25, '{"objective":"Integrar vocabulario práctico para viajes, alojamiento, vacaciones, tiempo, compras, salud y relaciones.","sections":[{"type":"grammar","title":"Gramática · Module 5 review","body":"Integrar vocabulario práctico para viajes, alojamiento, vacaciones, tiempo, compras, salud y relaciones.\n\nUsa expresiones funcionales completas y el tiempo verbal adecuado al contexto.","example":"We ___ a room before the holiday. (book)\nbooked","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Module 5 review","body":"reservation, ticket, forecast, refund, headache, comfortable, colleague.","example":"It was ___, so we bought a coat. (wind)\nwindy","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Module 5 review","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"We booked a room, took the train and visited a museum. It was windy, so we bought a coat. My friend had a headache, but she rested and felt better.","transcript":"We booked a room, took the train and visited a museum. It was windy, so we bought a coat. My friend had a headache, but she rested and felt better.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Module 5 review","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"We booked a room, took the train and visited a museum. It was windy, so we bought a coat. My friend had a headache, but she rested and felt better.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-51', 'english-a2', 51, 51, 'Making suggestions', 'Proponer planes con Shall we, Let''s, Why don''t we y How about.', 25, '{"objective":"Proponer planes con Shall we, Let''s, Why don''t we y How about.","sections":[{"type":"grammar","title":"Gramática · Making suggestions","body":"Proponer planes con Shall we, Let''s, Why don''t we y How about.\n\nShall we + base; Let''s + base; How about + noun/-ing; Why don''t we + base.","example":"___ we go for a walk?\nShall","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Making suggestions","body":"suggestion = sugerencia; meet = quedar; cinema = cine; Shall we...? = ¿Y si...?","example":"Let''s ___ at six.\nmeet","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Making suggestions","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"It''s Saturday. Shall we go to the cinema? We could meet at six. How about having dinner after the film?","transcript":"It''s Saturday. Shall we go to the cinema? We could meet at six. How about having dinner after the film?","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Making suggestions","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"It''s Saturday. Shall we go to the cinema? We could meet at six. How about having dinner after the film?","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-52', 'english-a2', 52, 52, 'Offers and requests', 'Ofrecer ayuda y pedir cosas cortésmente con Can I, Would you like me to, Could you.', 25, '{"objective":"Ofrecer ayuda y pedir cosas cortésmente con Can I, Would you like me to, Could you.","sections":[{"type":"grammar","title":"Gramática · Offers and requests","body":"Ofrecer ayuda y pedir cosas cortésmente con Can I, Would you like me to, Could you.\n\nCan I + base; Could you + base; Would you like me to + base.","example":"Can I ___ you? (help)\nhelp","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Offers and requests","body":"offer = oferta; request = petición; carry = llevar; lend = prestar; help = ayudar.","example":"Could you ___ the door? (open)\nopen","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Offers and requests","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"Your bag looks heavy. Can I carry it for you? Yes, please. Could you also lend me a pen? Of course.","transcript":"Your bag looks heavy. Can I carry it for you? Yes, please. Could you also lend me a pen? Of course.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Offers and requests","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"Your bag looks heavy. Can I carry it for you? Yes, please. Could you also lend me a pen? Of course.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-53', 'english-a2', 53, 53, 'Expressing opinions', 'Expresar opiniones y acuerdo/desacuerdo con I think, in my opinion, I agree.', 25, '{"objective":"Expresar opiniones y acuerdo/desacuerdo con I think, in my opinion, I agree.","sections":[{"type":"grammar","title":"Gramática · Expressing opinions","body":"Expresar opiniones y acuerdo/desacuerdo con I think, in my opinion, I agree.\n\nI think + clause; In my opinion, ...; I agree / I don''t think so.","example":"In my ___, this book is useful.\nopinion","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Expressing opinions","body":"opinion = opinión; agree = estar de acuerdo; useful = útil; boring = aburrido; prefer = preferir.","example":"I ___ with you. (agree)\nagree","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Expressing opinions","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"In my opinion, the new library is useful. I think it''s comfortable, although I prefer the old café. My friend agrees with me.","transcript":"In my opinion, the new library is useful. I think it''s comfortable, although I prefer the old café. My friend agrees with me.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Expressing opinions","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"In my opinion, the new library is useful. I think it''s comfortable, although I prefer the old café. My friend agrees with me.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-54', 'english-a2', 54, 54, 'Feelings and emotions', 'Describir emociones y distinguir adjetivos -ed y -ing (bored/boring, excited/exciting).', 25, '{"objective":"Describir emociones y distinguir adjetivos -ed y -ing (bored/boring, excited/exciting).","sections":[{"type":"grammar","title":"Gramática · Feelings and emotions","body":"Describir emociones y distinguir adjetivos -ed y -ing (bored/boring, excited/exciting).\n\n-ed describe cómo se siente una persona; -ing describe lo que provoca la emoción.","example":"I feel ___ about the trip. (excited)\nexcited","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Feelings and emotions","body":"excited = emocionado; exciting = emocionante; bored = aburrido; boring = aburrido (que aburre); proud = orgulloso.","example":"The trip is ___. (exciting)\nexciting","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Feelings and emotions","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"I felt excited before the trip because the plan was exciting. On the long journey I became bored, but I felt proud when we arrived.","transcript":"I felt excited before the trip because the plan was exciting. On the long journey I became bored, but I felt proud when we arrived.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Feelings and emotions","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"I felt excited before the trip because the plan was exciting. On the long journey I became bored, but I felt proud when we arrived.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-55', 'english-a2', 55, 55, 'The environment', 'Hablar del medio ambiente con should, recycling y acciones sostenibles.', 25, '{"objective":"Hablar del medio ambiente con should, recycling y acciones sostenibles.","sections":[{"type":"grammar","title":"Gramática · The environment","body":"Hablar del medio ambiente con should, recycling y acciones sostenibles.\n\nshould + base; recycle paper; save water; reduce waste; protect nature.","example":"We should ___ paper. (recycle)\nrecycle","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · The environment","body":"environment = medio ambiente; recycle = reciclar; pollution = contaminación; save = ahorrar; waste = residuos.","example":"Don''t ___ water. (waste)\nwaste","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · The environment","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"We should recycle paper and glass. We shouldn''t waste water, and we can walk or take the bus to reduce pollution.","transcript":"We should recycle paper and glass. We shouldn''t waste water, and we can walk or take the bus to reduce pollution.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · The environment","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"We should recycle paper and glass. We shouldn''t waste water, and we can walk or take the bus to reduce pollution.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-56', 'english-a2', 56, 56, 'Technology and communication', 'Hablar de dispositivos y acciones digitales con turn on/off, download, log in y send.', 25, '{"objective":"Hablar de dispositivos y acciones digitales con turn on/off, download, log in y send.","sections":[{"type":"grammar","title":"Gramática · Technology and communication","body":"Hablar de dispositivos y acciones digitales con turn on/off, download, log in y send.\n\nPhrasal verbs y comandos habituales; log in to an account; download an app.","example":"Please ___ the app.\ndownload","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Technology and communication","body":"download = descargar; log in = iniciar sesión; password = contraseña; attachment = archivo adjunto; device = dispositivo.","example":"Log ___ with your password.\nin","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Technology and communication","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"First, download the app. Then log in with your password and send the file as an attachment. Remember to turn off your device before the meeting.","transcript":"First, download the app. Then log in with your password and send the file as an attachment. Remember to turn off your device before the meeting.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Technology and communication","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"First, download the app. Then log in with your password and send the file as an attachment. Remember to turn off your device before the meeting.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-57', 'english-a2', 57, 57, 'Work and education', 'Hablar del trabajo, estudios, funciones y obligaciones con work as, study at y have to.', 25, '{"objective":"Hablar del trabajo, estudios, funciones y obligaciones con work as, study at y have to.","sections":[{"type":"grammar","title":"Gramática · Work and education","body":"Hablar del trabajo, estudios, funciones y obligaciones con work as, study at y have to.\n\nwork as + profesión; study at + institución; have to + verbo base.","example":"I work ___ a teacher.\nas","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Work and education","body":"colleague = compañero; degree = título; timetable = horario; task = tarea; deadline = fecha límite.","example":"I study ___ university.\nat","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Work and education","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"I work as a teaching assistant and study at university in the evening. I have to finish my assignment before Friday because the deadline is close.","transcript":"I work as a teaching assistant and study at university in the evening. I have to finish my assignment before Friday because the deadline is close.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Work and education","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"I work as a teaching assistant and study at university in the evening. I have to finish my assignment before Friday because the deadline is close.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-58', 'english-a2', 58, 58, 'Places and buildings', 'Describir lugares y edificios con there is/are, located in y preposiciones de lugar.', 25, '{"objective":"Describir lugares y edificios con there is/are, located in y preposiciones de lugar.","sections":[{"type":"grammar","title":"Gramática · Places and buildings","body":"Describir lugares y edificios con there is/are, located in y preposiciones de lugar.\n\nThere is + singular; there are + plural; located in/near/opposite.","example":"There ___ a museum in the square.\nis","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Places and buildings","body":"square = plaza; library = biblioteca; museum = museo; located = situado; building = edificio.","example":"There ___ two cafés near the river.\nare","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Places and buildings","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"There is a museum in the main square. The library is located opposite the station, and there are two cafés near the river.","transcript":"There is a museum in the main square. The library is located opposite the station, and there are two cafés near the river.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Places and buildings","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"There is a museum in the main square. The library is located opposite the station, and there are two cafés near the river.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-59', 'english-a2', 59, 59, 'Linking words', 'Unir ideas con and, but, because, so y although.', 25, '{"objective":"Unir ideas con and, but, because, so y although.","sections":[{"type":"grammar","title":"Gramática · Linking words","body":"Unir ideas con and, but, because, so y although.\n\nbecause introduce causa; so introduce resultado; but/although expresan contraste.","example":"I was tired, ___ I went to bed.\nso","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Linking words","body":"and = y; but = pero; because = porque; so = así que; although = aunque.","example":"We stayed in ___ it rained.\nbecause","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Linking words","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"It rained, so we stayed at home. Although I was tired, I finished my work because the deadline was today. I like tea and coffee, but I prefer tea.","transcript":"It rained, so we stayed at home. Although I was tired, I finished my work because the deadline was today. I like tea and coffee, but I prefer tea.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Linking words","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"It rained, so we stayed at home. Although I was tired, I finished my work because the deadline was today. I like tea and coffee, but I prefer tea.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-60', 'english-a2', 60, 60, 'Module 6 review', 'Integrar sugerencias, peticiones, opiniones, emociones, entorno, tecnología, trabajo, lugares y conectores.', 25, '{"objective":"Integrar sugerencias, peticiones, opiniones, emociones, entorno, tecnología, trabajo, lugares y conectores.","sections":[{"type":"grammar","title":"Gramática · Module 6 review","body":"Integrar sugerencias, peticiones, opiniones, emociones, entorno, tecnología, trabajo, lugares y conectores.\n\nCombina funciones comunicativas en frases naturales; evita dobles conectores y errores como I am agree.","example":"___ we meet at six? (suggestion)\nShall","exampleTranslation":"Aplica la regla y fíjate en el auxiliar, la forma verbal y el orden de las palabras."},{"type":"vocabulary","title":"Vocabulario · Module 6 review","body":"Shall we; Could you; I think; proud; recycle; download; work as; there is/are; because/so/although.","example":"I ___ it''s a useful course.\nthink","exampleTranslation":"Lee el significado en contexto y crea otra frase propia con las palabras clave."},{"type":"listening","title":"Listening · Module 6 review","body":"Escucha el diálogo breve de esta unidad. Primero identifica el tema; en la segunda escucha localiza nombres, acciones y detalles. Puedes reproducir el audio con voz inglesa.","audioText":"This week I felt excited because I finished Module 6. Shall we celebrate? Let''s meet in the main square—there is a café opposite the library. Although some units were hard, I think the course was useful, so I''ll keep practising.","transcript":"This week I felt excited because I finished Module 6. Shall we celebrate? Let''s meet in the main square—there is a café opposite the library. Although some units were hard, I think the course was useful, so I''ll keep practising.","transcriptTranslation":"Lee la transcripción después de intentar comprender el audio."},{"type":"reading","title":"Reading · Module 6 review","body":"Lee el texto breve dos veces: primero para captar la idea general y después para buscar la información precisa.","example":"This week I felt excited because I finished Module 6. Shall we celebrate? Let''s meet in the main square—there is a café opposite the library. Although some units were hard, I think the course was useful, so I''ll keep practising.","exampleTranslation":"Después de responder, vuelve al texto y señala la frase que justifica cada respuesta."}]}', 1);

-- A stable exercise number per lesson; all answer keys remain server-side.
-- Delete a previously partially applied A2 seed before re-inserting exercises; this avoids the duplicate-prompt trigger on retries.
DELETE FROM learning_exercises WHERE lesson_id GLOB 'a2-[0-9][0-9]';

