INSERT OR IGNORE INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, ai_generated, section_type, audio_text) VALUES ('a2-11-listening-01', 'a2-11', 31, 'multiple_choice', 'Which city has the speaker visited?', '["Rome.","Paris.","London.","Oxford."]', '{"correct":"Rome."}', 'Escucha el diálogo y busca la frase que contiene la respuesta. Transcripción: I have visited Rome and I have tried Italian food. My friend has been to Paris, but she hasn''t visited London yet.', 0, 'listening', 'I have visited Rome and I have tried Italian food. My friend has been to Paris, but she hasn''t visited London yet.');
