INSERT OR IGNORE INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, ai_generated, section_type, audio_text) VALUES ('a2-26-listening-01', 'a2-26', 31, 'multiple_choice', 'What will they do if it rains?', '["Stay at home.","Go to the beach.","Miss the train.","Visit the museum."]', '{"correct":"Stay at home."}', 'Escucha el diálogo y busca la frase que contiene la respuesta. Transcripción: If it rains tomorrow, we''ll stay at home. If the weather is good, we''ll go to the beach. If we leave late, we''ll miss the bus.', 0, 'listening', 'If it rains tomorrow, we''ll stay at home. If the weather is good, we''ll go to the beach. If we leave late, we''ll miss the bus.');
INSERT OR IGNORE INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, ai_generated, section_type, audio_text) VALUES ('a2-26-listening-02', 'a2-26', 32, 'multiple_choice', 'Which verb tense follows if in the First Conditional?', '["Present Simple.","Will + verb.","Past Simple.","Present Perfect."]', '{"correct":"Present Simple."}', 'Escucha el diálogo y busca la frase que contiene la respuesta. Transcripción: If it rains tomorrow, we''ll stay at home. If the weather is good, we''ll go to the beach. If we leave late, we''ll miss the bus.', 0, 'listening', 'If it rains tomorrow, we''ll stay at home. If the weather is good, we''ll go to the beach. If we leave late, we''ll miss the bus.');
INSERT OR IGNORE INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, ai_generated, section_type, audio_text) VALUES ('a2-26-listening-03', 'a2-26', 33, 'multiple_choice', 'Choose the correct sentence:', '["If we hurry, we''ll catch the bus.","If we will hurry, we catch the bus.","If we hurried, we''ll caught it.","If hurry, we''ll catching the bus."]', '{"correct":"If we hurry, we''ll catch the bus."}', 'Escucha el diálogo y busca la frase que contiene la respuesta. Transcripción: If it rains tomorrow, we''ll stay at home. If the weather is good, we''ll go to the beach. If we leave late, we''ll miss the bus.', 0, 'listening', 'If it rains tomorrow, we''ll stay at home. If the weather is good, we''ll go to the beach. If we leave late, we''ll miss the bus.');
