INSERT OR IGNORE INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, ai_generated, section_type, audio_text) VALUES ('a2-42-listening-01', 'a2-42', 31, 'multiple_choice', 'What kind of room does the guest book?', '["A double room.","A single room.","A dormitory.","A suite for a week."]', '{"correct":"A double room."}', 'Escucha el diálogo y busca la frase que contiene la respuesta. Transcripción: Hello, I''d like to book a double room for two nights. Is breakfast included? Yes, and check-in is from 2 pm. Check-out is at 11 am.', 0, 'listening', 'Hello, I''d like to book a double room for two nights. Is breakfast included? Yes, and check-in is from 2 pm. Check-out is at 11 am.');
INSERT OR IGNORE INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, ai_generated, section_type, audio_text) VALUES ('a2-42-listening-02', 'a2-42', 32, 'multiple_choice', 'When is check-out?', '["At 11 am.","At 2 pm.","At noon tomorrow.","At 9 am."]', '{"correct":"At 11 am."}', 'Escucha el diálogo y busca la frase que contiene la respuesta. Transcripción: Hello, I''d like to book a double room for two nights. Is breakfast included? Yes, and check-in is from 2 pm. Check-out is at 11 am.', 0, 'listening', 'Hello, I''d like to book a double room for two nights. Is breakfast included? Yes, and check-in is from 2 pm. Check-out is at 11 am.');
